{"function":"() => {
const props=['outline-style','outline-width','outline-color','box-shadow','border-top-color','border-bottom-color','background-color','color'];
const els=[...document.querySelectorAll('a[href],button,input,textarea,select,[tabindex]')].filter(e=>e.offsetParent!==null || e.getClientRects().length);
const out=[];
for(const e of els){ if(e.closest('.flatpickr-calendar')) continue;
 const s1=getComputedStyle(e); const b=props.map(p=>s1.getPropertyValue(p));
 e.focus({focusVisible:true}); const s2=getComputedStyle(e); const a=props.map(p=>s2.getPropertyValue(p));
 const diff=props.filter((p,i)=>b[i]!==a[i]);
 out.push((e.id||e.className||e.tagName)+' ti='+e.tabIndex+' focused='+(document.activeElement===e)+' diff='+diff.join(','));
 e.blur();}
return out.join('\n');}"}

